<?php
$stats=[]; foreach(['types'=>'SELECT COUNT(*) FROM equipment','equipment'=>'SELECT COUNT(*) FROM equipment_items','available'=>'SELECT COUNT(*) FROM equipment_items WHERE status=\'Available\'','onloan'=>'SELECT COUNT(*) FROM equipment_items WHERE status=\'On Loan\'','inspection'=>'SELECT COUNT(*) FROM equipment_items WHERE status=\'Awaiting Inspection\'','pending'=>'SELECT COUNT(*) FROM loan_requests WHERE status=\'Pending\'','overdue'=>'SELECT COUNT(*) FROM loans WHERE returned_at IS NULL AND due_date<CURDATE()'] as $k=>$sql) $stats[$k]=(int)$pdo->query($sql)->fetchColumn();
$recent=$pdo->query('SELECT a.*,u.full_name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 6')->fetchAll(); $upcoming=$pdo->query("SELECT l.id,l.due_date,b.full_name borrower,e.name equipment FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE l.returned_at IS NULL AND l.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 14 DAY) ORDER BY l.due_date LIMIT 6")->fetchAll(); $availability=$pdo->query("SELECT c.name,COUNT(i.id) total,SUM(i.status='Available') available FROM equipment_categories c LEFT JOIN equipment e ON e.category_id=c.id LEFT JOIN equipment_items i ON i.equipment_id=e.id GROUP BY c.id ORDER BY c.name")->fetchAll();
layout_start('Dashboard','dashboard'); ?><div class="page-heading"><div><p class="eyebrow">YOUR WORKSPACE</p><h1>Good <?=date('G')<12?'morning':(date('G')<17?'afternoon':'evening')?>, <?=h(explode(' ',user()['name'])[0])?></h1><p class="muted">A clear view of the equipment and people you support. Physical unit total includes retired items.</p></div><a class="button primary" href="?page=request-form">＋ New loan request</a></div><section class="stat-grid"><?php foreach([['types','Equipment types','◈'],['equipment','Physical equipment units','▦'],['available','Available now','✓'],['onloan','Currently on loan','↗'],['inspection','Awaiting inspection','◷'],['pending','Pending requests','▤'],['overdue','Overdue loans','!']] as [$k,$label,$icon]): ?><article class="stat-card"><span class="stat-icon"><?=$icon?></span><p><?=h($label)?></p><strong><?=$stats[$k]?></strong><?php if($k==='overdue' && $stats[$k]): ?><a class="stat-link" href="?page=overdue">Review overdue →</a><?php endif; ?></article><?php endforeach; ?></section><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Upcoming returns</h2><p class="muted">Due in the next 14 days</p></div><a href="?page=loans" class="text-link">All active loans</a></div><?php if(!$upcoming): ?><div class="table-empty">No returns due in the next two weeks.</div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Borrower</th><th>Equipment</th><th>Due date</th></tr></thead><tbody><?php foreach($upcoming as $r): ?><tr><td><?=h($r['borrower'])?></td><td><?=h($r['equipment'])?></td><td><?=date('j M Y',strtotime($r['due_date']))?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><section class="panel"><div class="panel-heading"><div><h2>Recent activity</h2><p class="muted">Latest actions in CareShare</p></div></div><?php if(!$recent): ?><div class="table-empty">Activity will appear here as your team works.</div><?php else: ?><ul class="activity-list"><?php foreach($recent as $r): ?><li><span class="activity-mark">·</span><div><strong><?=h($r['action'])?></strong><small><?=h($r['full_name']??'Borrower portal')?> · <?=date('j M, g:i a',strtotime($r['created_at']))?></small></div></li><?php endforeach; ?></ul><?php endif; ?></section></div><section class="panel availability-panel"><div class="panel-heading"><div><h2>Equipment availability</h2><p class="muted">Items ready to lend by category</p></div><a href="?page=reports&report=availability" class="text-link">View report →</a></div><div class="availability-grid"><?php foreach($availability as $a): $pct=(int)$a['total']?round((int)$a['available']/(int)$a['total']*100):0; ?><div class="availability-row"><div><strong><?=h($a['name'])?></strong><span><?=$a['available']??0?> of <?=$a['total']?> available</span></div><div class="availability-track"><i style="width:<?=$pct?>%"></i></div></div><?php endforeach; ?></div></section><?php layout_end();
